-- Technostat: each company retains its default owner; one real shared owner is
-- assigned to all company codes. The All node is virtual and not stored.
DO $technostat_operating_organizations$
DECLARE v_tenant_id uuid; v_actor uuid; v_meta constant jsonb:='{"_seed":{"pack":"technostat.operating-organizations","version":"2.0.0"}}'::jsonb;
BEGIN
 SELECT id INTO v_tenant_id FROM master.tenant WHERE realm_key='athyper' AND code='technostat'; IF v_tenant_id IS NULL THEN RAISE EXCEPTION '[202_operating_organizations] Technostat tenant not found'; END IF;
 SELECT id INTO v_actor FROM master.principal WHERE tenant_id=v_tenant_id AND code='seed.three-plane-provisioner' AND status='active'; IF v_actor IS NULL THEN RAISE EXCEPTION '[202_operating_organizations] Technostat seed principal not found'; END IF;
 PERFORM set_config('app.current_principal_id',v_actor::text,true);
INSERT INTO master.operating_organization (tenant_id,code,name,description,organization_kind,effective_from,metadata,status,created_by)
SELECT v_tenant_id,lower(code)||'-company-operations',name||' Operations','Default owner for '||name||' transactions.','company_operations',current_date,v_meta||jsonb_build_object('context',jsonb_build_object('is_company_default',true)),'active',v_actor FROM master.company_code WHERE tenant_id=v_tenant_id
UNION ALL SELECT v_tenant_id,'technostat-shared-operations','Technostat Shared Operations','Cross-company business owner for shared group operations.','shared_operations',current_date,v_meta,'active',v_actor
ON CONFLICT (tenant_id,code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,organization_kind=EXCLUDED.organization_kind,metadata=master.operating_organization.metadata||EXCLUDED.metadata,status='active',updated_at=now(),updated_by=v_actor;
 INSERT INTO master.operating_organization_company_assignment (tenant_id,operating_organization_id,company_code_id,participation_role,effective_from,metadata,status,created_by)
 SELECT v_tenant_id,org.id,company.id,'lead',current_date,v_meta,'active',v_actor FROM master.company_code company JOIN master.operating_organization org ON org.tenant_id=v_tenant_id AND org.code=lower(company.code)||'-company-operations' WHERE company.tenant_id=v_tenant_id
 UNION ALL SELECT v_tenant_id,org.id,company.id,CASE WHEN upper(company.code)='TKSA' THEN 'lead' ELSE 'participant' END,current_date,v_meta,'active',v_actor FROM master.company_code company JOIN master.operating_organization org ON org.tenant_id=v_tenant_id AND org.code='technostat-shared-operations' WHERE company.tenant_id=v_tenant_id
 ON CONFLICT (tenant_id,operating_organization_id,company_code_id,effective_from) DO UPDATE SET participation_role=EXCLUDED.participation_role,metadata=EXCLUDED.metadata,status='active',effective_until=NULL,updated_at=now(),updated_by=v_actor;
 INSERT INTO master.operating_organization_capability(tenant_id,operating_organization_id,capability_code,effective_from,metadata,status,created_by)
 SELECT org.tenant_id,org.id,capability.code,current_date,v_meta,'active',v_actor FROM master.operating_organization org CROSS JOIN LATERAL unnest(CASE WHEN org.organization_kind='company_operations' THEN ARRAY['finance','procurement','people','sales','operations','warehouse','projects'] ELSE ARRAY['finance','procurement','people','sales'] END) capability(code) WHERE org.tenant_id=v_tenant_id AND org.metadata#>>'{_seed,pack}'='technostat.operating-organizations'
 ON CONFLICT(tenant_id,operating_organization_id,capability_code,effective_from) DO UPDATE SET status='active',metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
INSERT INTO master.procurement_organization_profile (tenant_id,operating_organization_id,buying_model,default_currency,lead_company_code_id,metadata,created_by)
SELECT v_tenant_id,org.id,'federated',company.functional_currency,company.id,v_meta,v_actor FROM master.operating_organization org JOIN master.operating_organization_company_assignment a ON a.tenant_id=org.tenant_id AND a.operating_organization_id=org.id AND a.participation_role='lead' JOIN master.company_code company ON company.tenant_id=a.tenant_id AND company.id=a.company_code_id WHERE org.tenant_id=v_tenant_id AND org.metadata#>>'{_seed,pack}'='technostat.operating-organizations' AND EXISTS (SELECT 1 FROM master.operating_organization_capability capability WHERE capability.tenant_id=org.tenant_id AND capability.operating_organization_id=org.id AND capability.capability_code='procurement' AND capability.status='active')
ON CONFLICT (tenant_id,operating_organization_id) DO UPDATE SET buying_model=EXCLUDED.buying_model,default_currency=EXCLUDED.default_currency,lead_company_code_id=EXCLUDED.lead_company_code_id,metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
INSERT INTO master.sales_organization_profile (tenant_id,operating_organization_id,selling_model,default_currency,booking_company_code_id,invoicing_company_code_id,metadata,created_by)
SELECT v_tenant_id,org.id,'federated',company.functional_currency,company.id,company.id,v_meta,v_actor FROM master.operating_organization org JOIN master.operating_organization_company_assignment a ON a.tenant_id=org.tenant_id AND a.operating_organization_id=org.id AND a.participation_role='lead' JOIN master.company_code company ON company.tenant_id=a.tenant_id AND company.id=a.company_code_id WHERE org.tenant_id=v_tenant_id AND org.metadata#>>'{_seed,pack}'='technostat.operating-organizations' AND EXISTS (SELECT 1 FROM master.operating_organization_capability capability WHERE capability.tenant_id=org.tenant_id AND capability.operating_organization_id=org.id AND capability.capability_code='sales' AND capability.status='active')
ON CONFLICT (tenant_id,operating_organization_id) DO UPDATE SET selling_model=EXCLUDED.selling_model,default_currency=EXCLUDED.default_currency,booking_company_code_id=EXCLUDED.booking_company_code_id,invoicing_company_code_id=EXCLUDED.invoicing_company_code_id,metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
END;
$technostat_operating_organizations$;
